@Component("department-entity-projector")
public class DepartmentEntityProjector implements EntityProjector<Department>{
		
	// core constructor
	public DepartmentEntityProjector(ProjectorRegistry registry,
										DepartmentRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Department> getEntityClass() {
		return Department.class;
	}

    /*
	 * Insert a Department
	 * 
     * @param	entity Department
     */
    public Department create( Department entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Department
	 * 
     * @param	entity Department
     */
    public Department update( Department entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Department
	 * 
     * @param	id		UUID
     */
    public Department delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Department entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Facility
     * 
     * @param	parentId	UUID
     * @param	assignment 	Facility 
     * @return	Department
     */
    public Department assignFacility( UUID parentId, Facility assignment ) {
	    LOGGER.info("assigning Facility as " + assignment.toString() );

	    Department parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Facility.class, assignment.getFacilityId());

	    // ------------------------------------------
		// assign the Facility to the parent entity
		// ------------------------------------------ 
	    parentEntity.setFacility( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Facility
	 * 
	 * @param	parentId		UUID
	 * @return	Department
	 */
	public Department unAssignFacility( UUID parentId ) {
		Department parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Facility on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Facility on the parent entithy
		// ------------------------------------------     
	    parentEntity.setFacility(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the CareTeams
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Department
     */
    public Department addToCareTeams( UUID parentId, CareTeam addTo ) {
	    LOGGER.info("handling AssignCareTeamsToDepartmentEvent - " );
	    
	    Department parentEntity = repository.findById(parentId).get();
	    CareTeam child = registry.project( CareTeam.class, addTo.getCareTeamId());
	    
	    parentEntity.getCareTeams().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the CareTeams
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Department
     */
	public Department removeFromCareTeams( UUID parentId, CareTeam removeFrom ) {
	    LOGGER.info("handling RemoveCareTeamsFromDepartmentEvent " );
	
	    Department parentEntity = repository.findById(parentId).get();
	    CareTeam child = registry.project( CareTeam.class, removeFrom.getCareTeamId());
	    
	    parentEntity.getCareTeams().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Department via an FindDepartmentQuery
     * @return 	query	FindDepartmentQuery
     */
    @SuppressWarnings("unused")
    public Department find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Department - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Departments
     *
     * @param	query	FindAllDepartmentQuery 
     * @return 	List<Department> 
     */
    @SuppressWarnings("unused")
    public List<Department> findAll( FindAllDepartmentQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Department - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final DepartmentRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(DepartmentEntityProjector.class.getName());

}
